  1	\chapter{Games, strategies, and conditionally linear distributions}
  2	\label{chap:qpbt-games}
  3	% Paper label sec:games kept for cross-reference fidelity; resolves to the chapter number.
  4	\label{sec:games}
  5	
  6	This chapter records the vocabulary in which the quantum Pauli basis test and its analysis are phrased: two-player one-round games and tensor product strategies, the consistency and state-dependent distance calculus for families of measurements, and conditionally linear functions and distributions, the class of question distributions used by the tests of Chapter~\ref{chap:qpbt-test}. The presentation follows \cite{Ji2020MIPStar}; the distance calculus is imported there from \cite{Natarajan2018NEEXP} and \cite{Ji2020LowIndividualDegree}.
  7	
  8	\section{Measurements and observables}
  9	
 10	\begin{definition}[POVMs, sub-measurements, and observables]\label{def:povm-conventions}
 11		\uses{def:submeasurement}
 12		% Finiteness of the outcome set is stated explicitly here; the source leaves it implicit,
 13		% and the measurement and submeasurement definitions referenced below assume finite
 14		% outcome sets.
 15		Quantum measurements are modeled as positive operator-valued measures (POVMs). A \emph{POVM} on a finite-dimensional Hilbert space $\mathcal H$ is a family of positive semidefinite operators $\{M_a\}_{a \in S}$ indexed by outcomes $a$ ranging over a finite set $S$ such that $\sum_a M_a = \Id$; if the latter condition is relaxed to $\sum_a M_a \le \Id$, then $\{M_a\}$ is a \emph{sub-measurement}. (POVMs and sub-measurements are thus exactly the measurements and submeasurements of Definition~\ref{def:submeasurement}.) The probability that the measurement returns outcome $a$ on a state $\ket{\psi}$ is
 16		\[
 17			\Prb(a) = \bra{\psi} M_a \ket{\psi}\,.
 18		\]
 19		A POVM $M = \{M_a\}$ is \emph{projective} if each operator $M_a$ is a projector ($M_a^2 = M_a$); this automatically implies that $M_a M_b = M_b M_a = 0$ for distinct outcomes $a \ne b$. An \emph{observable} is a unitary matrix. A \emph{binary observable} is an observable $O$ such that $O^2 = \Id$, i.e.\ $O$ has eigenvalues in $\{-1,1\}$.
 20	
 21		Subscripts of a measurement index the outcome, and superscripts index different measurements. When the outcome of a measurement $\{M^x_{a,\,b}\}$ consists of two parts $a$ and $b$, we write $\{M^x_a\}$ and $\{M^x_b\}$ for its \emph{marginals}
 22		\[
 23			M^x_a = \sum_b M^x_{a,\,b}\,, \qquad M^x_b = \sum_a M^x_{a,\,b}\,;
 24		\]
 25		for every $x$ both marginals are again POVMs.
 26	\end{definition}
 27	
 28	\begin{definition}[Bracket notation for post-processed measurements]\label{def:bracket}
 29		\lean{MIPStarRE.Quantum.Measurement.postprocess}
 30		\leanok
 31		\uses{def:povm-conventions, def:post-processing}
 32		Let $\mathcal A$ and $\mathcal B$ be finite sets, let $\{M^x_a\}_{a \in \mathcal A}$ be a family of POVMs indexed by $x \in \mathcal X$, and let $f \colon \mathcal A \to \mathcal B$ be an arbitrary function. We write $\bigl\{ M^x_{[f(\cdot)=b]} \bigr\}$ for the POVM derived from $\{M^x_a\}$ by applying the function $f$ to the outcome before returning it:
 33		\[
 34			M^x_{[f(\cdot)=b]} = \sum_{a\,:\,f(a)=b} M^x_a\,,
 35		\]
 36		and $M^x_{[f(\cdot)=b]} = 0$ when $b$ is not in the image of $f$. When the outcome $a$ has a natural interpretation as a tuple $(a_1,\dots,a_k)$, we also write, for $i \in \{1,\dots,k\}$,
 37		\[
 38			M^x_{[a_i=b]} = \sum_{(a_1,\dots,a_k)\,:\,a_i=b} M^x_{(a_1,\dots,a_k)}\,.
 39		\]
 40		For each fixed $x$ this is the post-processing operation of Definition~\ref{def:post-processing}.
 41	\end{definition}
 42	
 43	\begin{remark}[Naimark dilation for strategies]\label{rem:naimark-for-games}
 44		The symmetrization argument of Lemma~\ref{lem:symmetric-strat} below invokes Naimark dilation in the form of Theorem~\ref{thm:naimark} (stated and proved in Chapter~\ref{chap:projective}): a bipartite state together with two sub-measurement families can be replaced, without changing any of the correlations $\bra{\psi} A^x_a \ot B^y_b \ket{\psi}$, by a product-extended state together with projective sub-measurements on the enlarged spaces. When the input families are complete measurements, the dilated projective sub-measurements can be completed by assigning the residual projector of each family to one fixed outcome; the resulting projective measurements reproduce the same correlations on the extended state, since the correlation-preservation identity forces the extended state to lie in the range of the total projector of each dilated family. This completed form, with genuinely projective measurements, is the one used in Lemma~\ref{lem:symmetric-strat}; for the proof the source refers to Theorem 5.1 of \cite{Ji2020LowIndividualDegree}, which is stated for complete measurements. The source follows its statement of the dilation theorem with a sentence announcing an ``orthogonalization lemma'' from the literature that is never actually stated there; nothing in this chapter depends on it.
 45	\end{remark}
 46	
 47	\section{Games and strategies}
 48	% Paper subsection label sec:strat kept for cross-reference fidelity.
 49	\label{sec:strat}
 50	
 51	\begin{definition}[Two-player one-round games]\label{def:game}
 52		A \emph{two-player one-round game} $\mathfrak G$ is specified by a tuple $(\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ where
 53		\begin{enumerate}
 54			\item $\mathcal X$ and $\mathcal Y$ are finite sets, called the \emph{question alphabets},
 55			\item $\mathcal A$ and $\mathcal B$ are finite sets, called the \emph{answer alphabets},
 56			\item $\mu$ is a probability distribution over $\mathcal X \times \mathcal Y$, called the \emph{question distribution}, and
 57			\item $D \colon \mathcal X \times \mathcal Y \times \mathcal A \times \mathcal B \to \{0,1\}$ is a function, called the \emph{decision predicate}.
 58		\end{enumerate}
 59	\end{definition}
 60	
 61	\begin{definition}[Tensor product strategies]\label{def:tensor-product-strategy}
 62		\uses{def:game, def:povm-conventions}
 63		A \emph{tensor product strategy} $\mathcal S$ for a game $\mathfrak G = (\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ is a tuple $(\ket{\psi}, A, B)$ where
 64		\begin{itemize}
 65			\item $\ket{\psi}$ is a pure quantum state, i.e.\ a unit vector in $\mathcal H_A \ot \mathcal H_B$ for finite-dimensional complex Hilbert spaces $\mathcal H_A$, $\mathcal H_B$,
 66			\item $A$ is a set $\{A^x\}$ such that for every $x \in \mathcal X$, $A^x = \{A^x_a\}_{a \in \mathcal A}$ is a POVM on $\mathcal H_A$, and
 67			\item $B$ is a set $\{B^y\}$ such that for every $y \in \mathcal Y$, $B^y = \{B^y_b\}_{b \in \mathcal B}$ is a POVM on $\mathcal H_B$.
 68		\end{itemize}
 69	\end{definition}
 70	
 71	\begin{definition}[Tensor product value]\label{def:tensor-product-value}
 72		\uses{def:tensor-product-strategy}
 73		The \emph{tensor product value} of a tensor product strategy $\mathcal S = (\ket{\psi}, A, B)$ with respect to a game $\mathfrak G = (\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ is
 74		\[
 75			\operatorname{val}^*(\mathfrak G, \mathcal S) = \sum_{x,\,y,\,a,\,b} \mu(x,y)\, D(x,y,a,b)\, \bra{\psi} A^x_a \ot B^y_b \ket{\psi}\,.
 76		\]
 77		For $v \in [0,1]$ we say that the strategy $\mathcal S$ \emph{passes (or wins) $\mathfrak G$ with probability $v$} if $\operatorname{val}^*(\mathfrak G, \mathcal S) \ge v$. The \emph{tensor product value} of $\mathfrak G$ is
 78		\[
 79			\operatorname{val}^*(\mathfrak G) = \sup_{\mathcal S} \operatorname{val}^*(\mathfrak G, \mathcal S)\,,
 80		\]
 81		where the supremum is taken over all tensor product strategies $\mathcal S$ for $\mathfrak G$.
 82	\end{definition}
 83	
 84	Unless specified otherwise, all strategies considered in what follows are tensor product strategies, and we simply call them \emph{strategies}; similarly, we refer to $\operatorname{val}^*(\mathfrak G)$ as the \emph{value} of the game $\mathfrak G$.
 85	
 86	% The source labels this definition def:projective-strategy. That label is already carried
 87	% by the low individual degree test track (Chapter 2), where it names the strategy format
 88	% specific to that test, so a distinct label is used here; see the following remark.
 89	\begin{definition}[Projective strategies]\label{def:projective-strategy-general}
 90		\lean{MIPStarRE.QPBT.Strategy.IsProjective}
 91		\leanok
 92		\uses{def:tensor-product-strategy, def:povm-conventions}
 93		A strategy $\mathcal S = (\ket{\psi}, A, B)$ is \emph{projective} if all the measurements $\{A^x_a\}_a$ and $\{B^y_b\}_b$ are projective.
 94	\end{definition}
 95	
 96	\begin{remark}[Two uses of the term ``projective strategy'']\label{rem:projective-strategy-relation}
 97		Definition~\ref{def:projective-strategy-general} is the general notion: a strategy for an arbitrary nonlocal game all of whose measurements are projective. The low individual degree chapters use the same term for the concrete data of a two-prover strategy for the $(m,q,d)$ low individual degree test (Definition~\ref{def:projective-strategy} in Chapter~\ref{chap:test}); that definition is the specialization of the present notion to the question format of that particular test. The two usages occur in disjoint contexts.
 98	\end{remark}
 99	
100	\begin{definition}[Symmetric games and symmetric strategies]\label{def:symmetric-game}
101		\lean{MIPStarRE.QPBT.SymmetricGame, MIPStarRE.QPBT.SymmetricGame.toGame, MIPStarRE.QPBT.SymmetricStrategy, MIPStarRE.QPBT.SymmetricStrategy.toStrategy}
102		\leanok
103		% Paper label: rem:symmetric-games (a definition environment carrying a rem: label in the
104		% source); relabeled here to match the environment kind.
105		\uses{def:game, def:tensor-product-strategy}
106		A game $\mathfrak G = (\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ is \emph{symmetric} if the question and answer alphabets are the same for both players (i.e.\ $\mathcal X = \mathcal Y$ and $\mathcal A = \mathcal B$), the distribution $\mu$ is symmetric (i.e.\ $\mu(x,y) = \mu(y,x)$ for all $x,y$), and the decision predicate $D$ treats both players symmetrically (i.e.\ $D(x,y,a,b) = D(y,x,b,a)$ for all $x,y,a,b$).
107	
108		A strategy $\mathcal S = (\ket{\psi}, A, B)$ is \emph{symmetric} if $\ket{\psi}$ is a (pure) state in $\mathcal H \ot \mathcal H$, for some Hilbert space $\mathcal H$, that is invariant under permutation of the two factors, and the measurement operators of both players are identical.
109	\end{definition}
110	
111	We often specify symmetric games $\mathfrak G$ and symmetric strategies $\mathcal S$ using a compact notation: we write $\mathfrak G = (\mathcal X, \mathcal A, \mu, D)$ and $\mathcal S = (\ket{\psi}, M)$, where $M$ denotes the set of measurement operators shared by both players.
112	
113	% Source statement (references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:94-99) kept in
114	% its original form. The proof below records the approximate form the source argument
115	% establishes and leaves the final attainment step unproved; see rem:symmetric-strat-limit.
116	\begin{lemma}[Symmetrization of strategies for symmetric games]\label{lem:symmetric-strat}
117		\lean{MIPStarRE.QPBT.exists_symmetric_projective_strategy}
118		\uses{def:symmetric-game, def:tensor-product-value, def:projective-strategy-general}
119		Let $\mathfrak G = (\mathcal X, \mathcal A, \mu, D)$ be a symmetric game such that $\operatorname{val}^*(\mathfrak G) = 1-\eps$ for some $\eps \ge 0$. Then there exists a symmetric and projective strategy $\mathcal S = (\ket{\psi}, M)$ such that $\operatorname{val}^*(\mathfrak G, \mathcal S) \ge 1-\eps$.
120	\end{lemma}
121	\begin{proof}
122		\uses{thm:naimark}
123		The symmetrization argument establishes the following approximate form of the conclusion: for every $\eps' > \eps$ there exists a symmetric and projective strategy of value at least $1-\eps'$. Indeed, fix $\eps' > \eps$. Since $\operatorname{val}^*(\mathfrak G)$ is the supremum of the values of all strategies, there exists a strategy $\mathcal S' = (\ket{\psi'}, A, B)$ with $\operatorname{val}^*(\mathfrak G, \mathcal S') \ge 1-\eps'$. Using Naimark dilation (Theorem~\ref{thm:naimark}), each dilated sub-measurement being completed to a projective measurement by assigning to one fixed outcome the residual projector of its family --- which changes no correlation on the extended state, as described in Remark~\ref{rem:naimark-for-games} above --- we may assume without loss of generality that $\ket{\psi'} \in \C^d_{A'} \ot \C^d_{B'}$ for some integer $d$ and that every $A^x$ and $B^x$ is a projective measurement. Let
124		\[
125			\ket{\psi} = \frac{1}{\sqrt 2}\, \bigl( \ket{0}_{A}\ket{1}_{B}\ket{\psi'}_{A'B'} + \ket{1}_{A}\ket{0}_{B}\ket{\psi'_\tau}_{A'B'} \bigr) \in \bigl(\C^2_{A} \ot \C^d_{A'}\bigr) \ot \bigl(\C^2_{B} \ot \C^d_{B'}\bigr)\,,
126		\]
127		where $\ket{\psi'_\tau}$ is obtained from $\ket{\psi'}$ by permuting the two players' registers; then $\ket{\psi}$ is invariant under permutation of the register pairs $AA'$ and $BB'$. For each question $x \in \mathcal X$ define the projective measurement $M^x = \{M^x_a\}_{a \in \mathcal A}$ on $\C^2 \ot \C^d$ by
128		\[
129			M^x_a = \ket{0}\bra{0} \ot A^x_a + \ket{1}\bra{1} \ot B^x_a\,,
130		\]
131		and let each player measure $M$ on their pair of registers. Because the decision predicate $D$ of the symmetric game treats the two players symmetrically, the resulting symmetric projective strategy $\mathcal S = (\ket{\psi}, M)$ satisfies $\operatorname{val}^*(\mathfrak G, \mathcal S) = \operatorname{val}^*(\mathfrak G, \mathcal S') \ge 1-\eps'$. Note that this construction preserves the value of the strategy it is applied to exactly.
132	
133		The statement asserts more, namely a single symmetric projective strategy of value at least $1-\eps$ itself. Passing from the family of strategies constructed above to one attaining the bound $1-\eps$ is an attainment step which the argument does not supply: the supremum defining $\operatorname{val}^*(\mathfrak G)$ in Definition~\ref{def:tensor-product-value} ranges over strategies of unbounded dimension and need not be attained. This step remains unproved; the obstruction, and the forms of the lemma that the argument does prove, are documented in \cite{gap:qpbt_symmetrization-attainment}. See also Remark~\ref{rem:symmetric-strat-limit}.
134	\end{proof}
135	
136	\begin{remark}[Attainment in the symmetrization lemma]\label{rem:symmetric-strat-limit}
137		The proof of Lemma~\ref{lem:symmetric-strat} yields, for each $\eps' > \eps$, a symmetric projective strategy of value at least $1-\eps'$. The conclusion as stated, at $\eps' = \eps$, does not follow from this: the dilated dimension $d$ may grow as $\eps' \downarrow \eps$, and the supremum defining $\operatorname{val}^*(\mathfrak G)$ in Definition~\ref{def:tensor-product-value} need not be attained by any strategy. The symmetrization construction itself is value-preserving, so the conclusion does hold whenever the hypothesis supplies an actual strategy of value at least $1-\eps$ rather than only the value of the game; every use of the lemma in the source proceeds from such a strategy, or from a strict lower bound on the value, and therefore consumes only what the proof establishes. The gap and the available repairs are documented in \cite{gap:qpbt_symmetrization-attainment}.
138	\end{remark}
139	
140	\begin{definition}[Commuting strategies]\label{def:comm-strategy}
141		\lean{MIPStarRE.QPBT.IsCommutingOn, MIPStarRE.QPBT.Strategy.IsCommuting}
142		\leanok
143		\uses{def:game, def:tensor-product-strategy}
144		Let $\mathfrak G = (\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ be a game, and let $\mathcal S = (\ket{\psi}, A, B)$ be a strategy for $\mathfrak G$ such that $\mathcal H_A = \mathcal H_B$. We say that $\mathcal S$ is a \emph{commuting strategy for $\mathfrak G$} if for all question pairs $(x,y)$ in the support of $\mu$ (i.e.\ all $(x,y)$ with $\mu(x,y) > 0$) we have
145		\[
146			[A^x_a, B^y_b] = 0 \qquad \text{for all } a \in \mathcal A,\ b \in \mathcal B\,,
147		\]
148		where $[A,B] = AB - BA$ denotes the commutator.
149	\end{definition}
150	
151	\begin{definition}[Consistent measurements]\label{def:consistent-measurement}
152		\lean{MIPStarRE.QPBT.Measurement.IsConsistentOn}
153		\leanok
154		\uses{def:povm-conventions}
155		Let $\mathcal A$ be a finite set, let $\ket{\psi} \in \mathcal H \ot \mathcal H$ be a state, and let $\{M_a\}_{a \in \mathcal A}$ be a projective measurement on $\mathcal H$. We say that \emph{$\{M_a\}_{a \in \mathcal A}$ is consistent on $\ket{\psi}$} if and only if
156		\[
157			\forall a \in \mathcal A\,, \qquad M_a \ot \Id_B\, \ket{\psi} = \Id_A \ot M_a\, \ket{\psi}\,.
158		\]
159		When the state $\ket{\psi}$ is clear from context we simply say that $\{M_a\}_{a \in \mathcal A}$ is consistent.
160	\end{definition}
161	
162	The terminology arises from the fact that when the measurement $\{M_a\}$ is performed on both registers of $\ket{\psi}$, the probability of obtaining twice the same outcome is
163	\[
164		\sum_a \bra{\psi} M_a \ot M_a \ket{\psi} = \sum_a \bra{\psi} \Id_A \ot (M_a)^2 \ket{\psi} = \sum_a \bra{\psi} \Id_A \ot M_a \ket{\psi} = 1\,,
165	\]
166	where the first equality is by the definition of consistency, the second uses that $\{M_a\}$ is projective, and the last uses $\sum_a M_a = \Id$.
167	
168	\begin{definition}[Consistent strategies]\label{def:consistent-strategy}
169		\lean{MIPStarRE.QPBT.IsConsistentStrategyOn, MIPStarRE.QPBT.SymmetricStrategy.IsConsistent}
170		\leanok
171		\uses{def:consistent-measurement, def:projective-strategy-general}
172		Let $\mathcal S = (\ket{\psi}, A, B)$ be a projective strategy with state $\ket{\psi} \in \mathcal H \ot \mathcal H$, for some Hilbert space $\mathcal H$, defined on question alphabets $\mathcal X$ and $\mathcal Y$ and answer alphabets $\mathcal A$ and $\mathcal B$, respectively. We say that $\mathcal S$ is \emph{consistent} if for all $x \in \mathcal X$ the measurement $\{A^x_a\}_{a \in \mathcal A}$ is consistent on $\ket{\psi}$, and for all $y \in \mathcal Y$ the measurement $\{B^y_b\}_{b \in \mathcal B}$ is consistent on $\ket{\psi}$.
173	\end{definition}
174	
175	We almost always restrict attention to symmetric strategies; in this case consistency implies that whenever both players are sent the same question, they provide the same answer.
176	
177	\begin{definition}[PCC and SPCC strategies]\label{def:spcc}
178		\lean{MIPStarRE.QPBT.Strategy.IsPCC, MIPStarRE.QPBT.SymmetricStrategy.IsSPCC}
179		\leanok
180		\uses{def:projective-strategy-general, def:consistent-strategy, def:comm-strategy, def:symmetric-game}
181		We say that a strategy $\mathcal S$ for a game $\mathfrak G$ is \emph{PCC} if it is projective, consistent, and commuting for $\mathfrak G$. Additionally, we say that a PCC strategy $\mathcal S$ is \emph{SPCC} if it is furthermore symmetric.
182	\end{definition}
